static ssize_t show_values ( struct device * dev , struct device_attribute * attr , char * buf ) { struct hidma_mgmt_dev * mdev = dev_get_drvdata ( dev ) ; unsigned int i ; for ( i = 0 ; i < ARRAY_SIZE ( hidma_mgmt_files ) ; i ++ ) { if ( strcmp ( attr -> attr . name , hidma_mgmt_files [ i ] . name ) == 0 ) { sprintf ( buf , "%d\n" , hidma_mgmt_files [ i ] . get ( mdev ) ) ; break ; } } return strlen ( buf ) ; } 